ById('close');        var panel = document.getElementById('panel');        var body = document.querySelector('body');        if (panel.style.display === 'none') {            panel.style.display = 'block';            body.style.overflow = 'hidden';        } else {            panel.style.display = 'none';            body.style.overflow = 'auto';        }        closePanelButton.addEventListener('click', function() {            panel.style.display = 'none';            body.style.overflow = 'auto';        });    }</script><script type="text/javascript">    const dropdownBtn = document.getElementById('dropdown-btn');    const dropdownMenu = document.getElementById('dropdown-menu');    const c= document.getElementById("dropdown-btn");    dropdownBtn.addEventListener('click', function()    {        if (dropdownMenu.style.display === 'block')        {            dropdownMenu.style.display = 'none';            c.style["border"]="none";        }        else        {            c.style["border"]="1px solid black";            dropdownMenu.style.display = 'block';        }    });</script>